WITH customer_returns AS ( SELECT cr.cr_returning_customer_sk AS cust_sk, SUM(cr.cr_return_amount) AS total_return_amount, COUNT(*) AS return_cnt FROM catalog_returns cr GROUP BY cr.cr_returning_customer_sk ) SELECT c.c_customer_id, c.c_first_name, c.c_last_name, cd.cd_marital_status, cd.cd_credit_rating, cr.total_return_amount, cr.return_cnt, (year(current_date) - c.c_birth_year) AS customer_age, ds.d_date AS first_sales_date, DENSE_RANK() OVER (ORDER BY cr.total_return_amount DESC) AS return_amount_rank, CASE WHEN cr.total_return_amount > 5000 THEN 'VIP' WHEN cr.total_return_amount > 2000 THEN 'Gold' ELSE 'Silver' END AS tier FROM customer_returns cr JOIN customer c ON cr.cust_sk = c.c_customer_sk JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk JOIN date_dim ds ON c.c_first_sales_date_sk = ds.d_date_sk ORDER BY cr.total_return_amount DESC LIMIT 5
